<?php
declare(strict_types=1);
use Hls\Middleware\Access;
$expStart=count($checks);
$makeExp=fn(int $actor)=>new Hls\Services\Expedition(new Hls\Repositories\ExpeditionRepository($repo,new Hls\Services\ExpeditionAccess($repo,new Access($repo,$users->find($actor)))),$audit);
$exp=$makeExp($adminId);$expScoped=$makeExp($scopedId);$expOwner=$makeExp($ownerId);
$receiver=$md->save('parties',['code'=>'EXP-RECEIVER','name'=>'Penerima tujuan V2','branch_id'=>(string)$b,'party_role'=>'receiver','active'=>'1']);
$expRoute=(string)$masterFixtures['routes']['id'];
$dnInput=['document_date'=>'2026-10-24','route_id'=>$expRoute,'customer_id'=>(string)$masterFixtures['customers']['id'],'sender_id'=>(string)$masterFixtures['parties']['id'],'receiver_id'=>(string)$receiver,'description'=>'Mesin uji satu deskripsi','quantity'=>'2.125','unit'=>'Koli','weight'=>'','volume'=>'0','note'=>'Catatan internal tidak menjadi timeline','request_key'=>bin2hex(random_bytes(32))];
$dn=$expScoped->save('dn',$dnInput);check($dn>0,'DN awal dibuat oleh cabang asal dengan pilihan tujuan terikat rute');
$doc=$exp->data->find('dn',$dn);check($doc['status']==='created'&&$doc['weight']===null&&$doc['volume']==='0.000','DN awal mempertahankan NULL versus nol tanpa status perjalanan');
check(str_starts_with($doc['number'],'INT-DN-'),'DN memakai identifier internal Q04');
check($expScoped->save('dn',$dnInput)===$dn,'Replay create DN idempoten');
rejects(fn()=>$expScoped->save('dn',array_replace($dnInput,['description'=>'Berbeda'])),'Token create tidak dipakai payload berbeda',409);
check(count($exp->data->events('dn',$dn))===1,'Replay tidak menggandakan event');
foreach(['quantity'=>'0','weight'=>'-1','volume'=>'1.0001','document_date'=>'2026-02-31','sender_id'=>(string)$receiver] as $field=>$value)rejects(fn()=>$exp->save('dn',array_replace($dnInput,[$field=>$value,'request_key'=>bin2hex(random_bytes(32))])),'Validasi DN '.$field,422);
rejects(fn()=>$expOwner->save('dn',$dnInput),'Owner tidak memiliki mutasi DN',403);
$edit=$dnInput+['id'=>(string)$dn,'version'=>'1'];$edit['description']='Deskripsi terkoreksi sebelum manifest';check($expScoped->save('dn',$edit)===$dn,'DN awal dapat diedit dengan version');
rejects(fn()=>$expScoped->save('dn',$edit),'Edit stale ditolak',409);check($exp->data->find('dn',$dn)['number']===$doc['number'],'Identifier DN tidak berubah setelah edit');
$manifestInput=['document_date'=>'2026-10-24','route_id'=>$expRoute,'vehicle_id'=>(string)$masterFixtures['vehicles']['id'],'driver_id'=>(string)$masterFixtures['drivers']['id'],'note'=>'Draf belum berangkat','request_key'=>bin2hex(random_bytes(32))];
$manifest=$expScoped->save('manifest',$manifestInput);check($manifest>0&&$expScoped->save('manifest',$manifestInput)===$manifest,'Manifest draf dan replay idempoten');
$dn2=$expScoped->save('dn',array_replace($dnInput,['request_key'=>bin2hex(random_bytes(32))]));
rejects(fn()=>$expScoped->attach($manifest,[(string)$dn,(string)$dn2,'999999'],1),'Batch dengan satu DN tidak tersedia ditolak atomik',404);
check(!$exp->data->active($dn)&&!$exp->data->active($dn2),'Batch gagal tidak meninggalkan anggota parsial');
$expScoped->attach($manifest,[(string)$dn,(string)$dn2],1);check(count($exp->data->members($manifest))===2,'Manifest menampung banyak DN sesuai rute persis');
rejects(fn()=>$expScoped->attach($manifest,[(string)$dn],1),'Replay attach/version usang ditolak',409);
rejects(fn()=>$expScoped->save('dn',array_replace($edit,['version'=>'3'])),'DN dalam manifest tidak dapat diedit',409);
check($exp->data->find('dn',$dn)['status']==='created'&&$exp->data->find('manifest',$manifest)['status']==='draft','Keanggotaan tidak membuat status keberangkatan/tiba/diterima');
$other=$expScoped->save('manifest',array_replace($manifestInput,['request_key'=>bin2hex(random_bytes(32))]));
rejects(fn()=>$expScoped->attach($other,[(string)$dn],1),'Satu DN tidak masuk dua manifest aktif',409);
rejects(fn()=>$repo->run('INSERT INTO exp_manifest_items(manifest_id,dn_id,attached_by) VALUES (?,?,?)',[$other,$dn,$adminId]),'Unique active DN melindungi di database');
rejects(fn()=>$repo->run('DELETE FROM exp_dns WHERE id=?',[$dn]),'FK mempertahankan DN dengan histori');
rejects(fn()=>$repo->run('UPDATE exp_dns SET receiver_id=? WHERE id=?',[$masterFixtures['parties']['id'],$dn]),'Composite FK menolak penerima dari cabang yang salah');
$repo->run("CREATE TRIGGER exp_fail_audit BEFORE INSERT ON audit_logs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test failure'");
$beforeCount=(int)$repo->one('SELECT COUNT(*) n FROM exp_dns')['n'];
try{rejects(fn()=>$exp->save('dn',array_replace($dnInput,['request_key'=>bin2hex(random_bytes(32))])),'Kegagalan audit menolak pembuatan DN');}finally{$repo->run('DROP TRIGGER exp_fail_audit');}
check((int)$repo->one('SELECT COUNT(*) n FROM exp_dns')['n']===$beforeCount,'Rollback audit tidak meninggalkan dokumen/event');
for($i=0;$i<11;$i++)$expScoped->save('dn',array_replace($dnInput,['description'=>'Pagination '.$i,'request_key'=>bin2hex(random_bytes(32))]));
check(count($exp->data->listing('dn',['page'=>'1'])['rows'])===10&&count($exp->data->listing('dn',['page'=>'2'])['rows'])>=3,'Pagination DN memakai query database');
check($exp->data->listing('dn',['q'=>$doc['number']])['pagination']['total']===1,'Pencarian nomor DN');
check($exp->data->listing('dn',['status'=>'received'])['pagination']['total']===0,'Tidak ada penerimaan fiktif');
rejects(fn()=>$expScoped->data->listing('dn',['branch'=>(string)$b]),'Filter cabang terlarang ditolak',403);
rejects(fn()=>$exp->data->listing('dn',['from'=>'2026-10-25','until'=>'2026-10-24']),'Rentang tanggal terbalik ditolak',422);
$third=$md->save('branches',['code'=>'EXP-SECRET','name'=>'Cabang tidak terlibat','active'=>'1']);
$thirdUser=$master->user(['name'=>'Petugas asing','email'=>'exp-foreign@example.test','role_id'=>(string)$roles['Admin Pengirim'],'password'=>$password,'active'=>'1','branches'=>[(string)$third]]);
$foreign=$makeExp($thirdUser);rejects(fn()=>$foreign->data->find('dn',$dn),'ID DN cabang tidak terlibat ditolak',404);
check($foreign->data->listing('dn',[])['pagination']['total']===0,'Daftar DN cabang lain kosong');
$raceDn=$expScoped->save('dn',array_replace($dnInput,['request_key'=>bin2hex(random_bytes(32))]));
$raceManifests=[$expScoped->save('manifest',array_replace($manifestInput,['request_key'=>bin2hex(random_bytes(32))])),$expScoped->save('manifest',array_replace($manifestInput,['request_key'=>bin2hex(random_bytes(32))]))];
$outcomes=expeditionWorkers([['actor'=>$adminId,'manifest'=>$raceManifests[0],'dn'=>$raceDn],['actor'=>$scopedId,'manifest'=>$raceManifests[1],'dn'=>$raceDn]]);sort($outcomes);check($outcomes===['CONFLICT','OK'],'Dua proses bersamaan hanya satu manifest aktif');
check((int)$repo->one('SELECT COUNT(*) n FROM exp_manifest_items WHERE dn_id=? AND removed_at IS NULL',[$raceDn])['n']===1,'Hasil concurrency mempertahankan satu anggota aktif');
foreach(['/trucking/dns','/trucking/manifests','/trucking/tracking'] as $path){check(http($path,$anonJar)['status']===200,'Route Trucking aktual '.$path);check(http($path.'?mode=detail&id='.($path==='/trucking/manifests'?$manifest:$dn),$ownerJar)['status']===200,'Owner baca sesuai scope '.$path);}
check(http('/trucking/dns',$anonJar,['action'=>'save'])['status']===403,'POST DN tanpa CSRF ditolak');
$expToken=token(http('/trucking/dns',$anonJar));
check(http('/trucking/manifests',$anonJar,['csrf'=>$expToken,'action'=>'depart','id'=>(string)$manifest,'version'=>(string)$exp->data->find('manifest',$manifest)['version'],'request_key'=>bin2hex(random_bytes(32))])['status']===409,'Manifest draf belum dikonfirmasi tidak dapat berangkat');
check(http('/trucking/dns',$ownerJar,['csrf'=>token(http('/',$ownerJar)),'action'=>'save']+$dnInput)['status']===403,'Owner POST ditolak backend');
check(http('/trucking/tracking?mode=detail&id='.$dn,$anonJar)['status']===200,'Tracking internal menampilkan event aktual');
check(!str_contains(http('/trucking/tracking?mode=detail&id='.$dn,$anonJar)['body'],'Catatan internal tidak menjadi timeline'),'Tracking tidak menampilkan detail JSON event rahasia');
foreach(['/trucking/transit','/trucking/receipts','/trucking/claims'] as $path)check(http($path,$anonJar)['status']===200,'Route operasional nyata '.$path);
$expeditionFixtures=['dn'=>$dn,'manifest'=>$manifest,'route'=>$expRoute,'dnInput'=>$dnInput,'manifestInput'=>$manifestInput];
file_put_contents(__DIR__.'/results/expedition-integration.json',json_encode(['date'=>date(DATE_ATOM),'passed'=>count($checks)-$expStart,'checks'=>array_slice($checks,$expStart)],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
